SELECT MESSAGEID as messageId, CMFUSERID as cmfUserId, MESSAGETYPE as messageType, TEMPLATECODE as templateCode, JSONDATA as jsonData, SENDSTATUS as sendStatus, TO_CHAR(INSERTTIME,'YYYY-MM-DD HH24:MI:SS') AS insertTime, TO_CHAR(UPDATETIME,'YYYY-MM-DD HH24:MI:SS') AS updateTime
FROM CMF_WEIXIN_PUSHMESSAGE
WHERE MESSAGEID = #{messageId} AND SENDSTATUS = #{sendStatus}
